import sympy
from sympy import QQ, ZZ
from sympy.ntheory import primefactors
import math

# Top-level setup
# No specific named objects required for this domain, but we can define some basics
# The witness is expected to be a tuple (n, m) representing the ring Z/nZ and the ideal generated by m,
# or a dictionary {'R': n, 'm': m}.

def conditions(witness) -> list[bool]:
    """
    Checks if the witness is a valid counterexample.
    Returns [H_1_ok, neg_Q_ok].
    """
    try:
        # Extract R (represented by n) and m from the witness
        if isinstance(witness, dict):
            if 'R' in witness and 'm' in witness:
                n = witness['R']
                m = witness['m']
            elif 'n' in witness and 'm' in witness:
                n = witness['n']
                m = witness['m']
            else:
                return [False, False]
        elif isinstance(witness, tuple) and len(witness) == 2:
            n, m = witness
        else:
            return [False, False]
            
        # Case 1: R is QQ or ZZ
        if n in (QQ, ZZ):
            h1 = True  # QQ and ZZ are commutative rings
            
            # The Jacobson radical of QQ and ZZ is the zero ideal {0}
            if isinstance(m, (int, sympy.Integer)):
                q = (int(m) == 0)
                return [h1, not q]
            elif isinstance(m, (list, tuple)) and all(isinstance(x, (int, sympy.Integer)) for x in m):
                q = all(int(x) == 0 for x in m)
                return [h1, not q]
            return [False, False]
            
        # Case 2: R is Z/nZ (represented by an integer n >= 2)
        if isinstance(n, (int, sympy.Integer)) and n >= 2:
            n = int(n)
            h1 = True  # Z/nZ is a commutative ring for n >= 2
            
            # The Jacobson radical of Z/nZ is generated by the product of its distinct prime factors
            rad_n = 1
            for p in primefactors(n):
                rad_n *= p
                
            # Determine the generator of the ideal m in Z/nZ
            if isinstance(m, (int, sympy.Integer)):
                ideal_m = math.gcd(int(m), n)
            elif isinstance(m, (list, tuple)) and all(isinstance(x, (int, sympy.Integer)) for x in m):
                ideal_m = n
                for gen in m:
                    ideal_m = math.gcd(ideal_m, int(gen))
            else:
                return [False, False]
                
            # The ideals are equal in Z/nZ iff their canonical generators (divisors of n) are equal
            q = (rad_n == ideal_m)
            
            return [h1, not q]
            
    except Exception:
        pass
        
    return [False, False]

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "¬Q: The Jacobson radical of R is not exactly the ideal m"
]

N_HYP = 1
NEG_Q_INDEX = 1